class Solution { int answer=0;array<int,4> dfs(TreeNode* node){if(!node)return {1,INT_MAX,INT_MIN,0};auto left=dfs(node->left),right=dfs(node->right);if(left[0]&&right[0]&&node->val>left[2]&&node->val<right[1]){int sum=left[3]+right[3]+node->val;answer=max(answer,sum);return {1,min(node->val,left[1]),max(node->val,right[2]),sum};}return {0,0,0,0};}public:int maxSumBST(TreeNode* root){dfs(root);return answer;} };
